const input = $input.item.json.body || $input.item.json || {};

const pautas = [
  { formato: "autoridade", tema: "Por que comer pouco desacelera o metabolismo e bloqueia a queima de gordura?", foco: "Fisiologia e Termogênese" },
  { formato: "prato", tema: "Estratégia de reposição de glicogênio e reparo muscular no pós-treino intenso.", foco: "Alimentação Esportiva e Macros" },
  { formato: "ciencia", tema: "Treinar em jejum vs Treinar alimentado: o que a ciência do ACSM realmente diz?", foco: "Mito vs Evidência Científica" },
  { formato: "autoridade", tema: "Sono de baixa qualidade: o sabotador invisível da hipertrofia e emagrecimento.", foco: "Hormônios e Recuperação" },
  { formato: "prato", tema: "Café da manhã hiperproteico para saciedade e foco mental até o almoço.", foco: "Densidade Nutricional" }
];

let formato = input.formato || input.format || "";
let tema = input.tema || input.theme || input.chatInput || "";

if (!tema) {
  const sorteado = pautas[Math.floor(Math.random() * pautas.length)];
  formato = sorteado.formato;
  tema = sorteado.tema;
}

if (!formato) {
  const formatosValidos = ["autoridade", "prato", "ciencia"];
  formato = formatosValidos[Math.floor(Math.random() * formatosValidos.length)];
}

const fotosDra = [
  "https://isabelamunoznutri.com.br/assets/images/isa_1.png",
  "https://isabelamunoznutri.com.br/assets/images/isa_2.png",
  "https://isabelamunoznutri.com.br/assets/images/isa_3.png"
];

const fotoSelecionada = fotosDra[Math.floor(Math.random() * fotosDra.length)];

return [{
  json: {
    formato,
    tema,
    fotoDra: fotoSelecionada,
    logoUrl: "https://isabelamunoznutri.com.br/assets/images/logo_assinatura.png",
    instagram: "@nutri.isabelamunoz",
    crm: "Nutricionista Clínica & Esportiva de Elite | Certificação ACSM"
  }
}];

const params = $('Preparar_Parametros').first().json;
const rawAI = $('Gerar_Conteudo_IA').first().json.text || $('Gerar_Conteudo_IA').first().json.response || '{}';

let content = {};
try {
  content = typeof rawAI === 'string' ? JSON.parse(rawAI) : rawAI;
} catch (e) {
  content = { erro: "Falha no parse do JSON da IA", raw: rawAI };
}

return [{
  json: {
    status: "conteudo_gerado",
    formato: params.formato,
    tema: params.tema,
    fotoDra: params.fotoDra,
    logoUrl: params.logoUrl,
    instagram: params.instagram,
    crm: params.crm,
    dadosPost: content,
    legendaFinal: content.legenda_instagram || "Conteúdo gerado pela equipe da Dra. Isabela Muñoz.",
    promptImagemDalle: content.prompt_imagem_dalle || "Athletic training nutrition aesthetics dark gold mood."
  }
}];

const post = $('Formatar_HTML_Final').first().json;
const dalleResult = $input.item.json;
const imagemGeradaUrl = dalleResult.data && dalleResult.data[0] ? dalleResult.data[0].url : "";

return [{
  json: {
    previewStatus: "pronto_para_aprovacao",
    formato: post.formato,
    tema: post.tema,
    dadosPost: post.dadosPost,
    fotoDraOficial: post.fotoDra,
    imagemIaUrl: imagemGeradaUrl,
    legendaInstagram: post.legendaFinal
  }
}];
